import React, { useContext,useState } from "react";
import PasswordContext from "../store/password-context";
import Modal from "../UI/Modal";
const SavedPassword = () => {
  const usePassword = useContext(PasswordContext);
  const [editingItem, setEditingItem] = useState(null);

  const deleteHandler = (itemId) => {
    usePassword.removeItem(itemId);
  };

  const editItemHandler = (item) => {
    setEditingItem(item);
  };

  return (
    <div>
      {usePassword.openProduct && (
        <ul>
          <h3>All Passwords details :</h3>
          {usePassword.item.map((item) => (
            <li key={item.id} style={{ display: "flex" }}>
              <p>Title: {item.title} </p>
              <p style={{ marginLeft: "10px", marginRight: "10px" }}>
                Password :{item.password}
              </p>
              <button
                style={{
                  cursor: "pointer",
                  height: "25px",
                  width: "80px",
                  alignSelf: "center",
                }}
                onClick={() => deleteHandler(item.id)}
              >
                Delete
              </button>
              <button
                style={{
                  cursor: "pointer",
                  height: "25px",
                  width: "80px",
                  alignSelf: "center",
                }}
                onClick={() => editItemHandler(item)}
              >
                Edit
              </button>
            </li>
          ))}
        </ul>
      )}
      {editingItem && (
        <Modal>
          <UserForm
            onEditItem={(updatedItem) => {
              usePassword.editItem(editingItem.id, updatedItem);
              setEditingItem(null); // Close the modal
            }}
            editingItem={editingItem}
          />
        </Modal>
      )}
    </div>
  );
};
export default SavedPassword;
